import Foundation
import OpenAPIRuntime

/// Clean names for the generated control-plane DTOs.
///
/// The generator nests everything under `Components.Schemas.*`. Aliasing here
/// means UI code says `LoopState`, and a future generator rename lands in one
/// file instead of across every view.
///
/// Everything in this file is a *wire* type: the spec owns its shape, it carries
/// no behaviour, and it is regenerated by `Tools/generate.sh`. Where a type needs
/// behaviour it gets an extension below — never a parallel hand-written struct,
/// because two decoders for one wire format is exactly the drift this layout
/// exists to prevent.
///
/// The one shape deliberately absent is `Param`. The spec types it only under
/// `SettingsScope.fields`, while `JobInfo.params` and `Registry.modules[]`
/// deliver the same thing as untyped JSON — so it is hand-written in
/// `Param.swift` and serves all three. `Tools/normalize_spec.py` removes the
/// generated version so there is only ever one decoder for it.

// MARK: - Pairing

public typealias Health = Components.Schemas.Health
public typealias WhoAmI = Components.Schemas.WhoAmI

extension Health {
    public var isOK: Bool { status == "ok" }

    /// Guards against pointing the app at some *other* service that happens to
    /// answer on :8100 — a plausible mistake when typing a LAN address by hand.
    public var isWindex: Bool { service == "windex" }

    /// Whether the backend has a write token configured. Absent means no.
    public var needsToken: Bool { authRequired ?? false }
}

