// MARK: - Bridging the generator's untyped containers

extension OpenAPIObjectContainer {
    /// Re-decode an open container as a concrete type.
    ///
    /// The generator represents `additionalProperties: true` and untyped objects
    /// as `OpenAPIObjectContainer`, which is a `[String: (any Sendable)?]` and
    /// can't be `Decodable`-ed directly. Round-tripping through JSON is the
    /// supported way back to a typed value, and it is how `JobInfo.params` and
    /// `Registry.modules[]` become `Param`s.
    public func decode<T: Decodable>(_ type: T.Type = T.self) throws -> T {
        do {
            let data = try JSONEncoder().encode(self)
            return try JSONDecoder().decode(T.self, from: data)
        } catch {
            throw WindexError.decoding(underlying: error)
        }
    }
}

extension ActionResult {
    /// A mutating call's acknowledgement carries only `ok`/`detail` in common —
    /// each action returns the state it just set, so the interesting keys land in
    /// `additionalProperties`. These read the ones the server actually sends.

    /// What was started, e.g. `"ccnews-sync"` (`{"started": name, "pid": N}`).
    public var started: String? {
        additionalProperties.value["started"] as? String
    }

    /// The pid of a detached process, for the actions that spawn one. Its
    /// presence means *accepted*, not *finished*.
    public var pid: Int? {
        additionalProperties.value["pid"] as? Int
    }

    /// Whether the loop/ingest toggle landed on, for the desired-state calls.
    public var enabled: Bool? {
        additionalProperties.value["enabled"] as? Bool
    }

    /// The source a loop or ingest toggle applied to.
    public var source: String? {
        additionalProperties.value["source"] as? String
    }

    /// The resulting state, e.g. `"up"` / `"disabled"`.
    public var state: String? {
        additionalProperties.value["state"] as? String
    }

    /// Whichever key this action reports, for a generic confirmation message.
    public var summary: String {
        detail ?? started ?? state ?? (ok == true ? "ok" : "done")
    }
}

extension JobInfo {
    /// This job's arguments as form controls.
    ///
    /// `params` is untyped in the spec but is `Param.describe()` on the wire —
    /// the same shape settings use, which is the point of `Param` being generic.
    /// Job params come back with `enforce: "reject"`, so the form must refuse
    /// out-of-range input rather than clamping it.
    ///
    /// An all-open object generates as a wrapper holding a single
    /// `additionalProperties` container, so the payload is unwrapped before the
    /// round-trip.
    public func parameters() throws -> [String: Param] {
        try params?.additionalProperties.decode([String: Param].self) ?? [:]
    }
}

extension RecipeRun {
    /// The frozen runtime config used to create this run.
    public func parameters() throws -> [String: JSONValue] {
        try params?.additionalProperties.decode([String: JSONValue].self) ?? [:]
    }

    public var isTerminal: Bool {
        ["succeeded", "failed", "cancelled"].contains(state)
    }
}
